FILES = {'src/adapter_pool_frozen_preclassifier.py': '"""DistilBERT classifier-stack control with a frozen hidden pre-classifier."""\nimport torch\nfrom src.adapter_pool_fixed_memory import FixedMemoryCAUV1AdapterPool, FixedMemoryHeadOnlyCAUV1AdapterPool\n\n\ndef assert_frozen_preclassifier(model):\n    layer = model.base_model.model.pre_classifier\n    originals = dict(layer.original_module.named_parameters())\n    assert set(originals) == {\'weight\', \'bias\'}\n    for name, parameter in layer.named_parameters():\n        assert not parameter.requires_grad\n        assert torch.equal(parameter, originals[name.rsplit(\'.\', 1)[-1]])\n    return sum(p.numel() for n, p in model.named_parameters()\n               if \'.pre_classifier.modules_to_save.\' in n)\n\n\nclass FrozenPreClassifierMixin:\n    def freeze_preclassifier(self):\n        for name, parameter in self.model.named_parameters():\n            if \'.pre_classifier.\' in name:\n                parameter.requires_grad_(False)\n\n    def activate(self, name):\n        super().activate(name)\n        self.freeze_preclassifier()\n\n    def _new_optimizer(self):\n        self.freeze_preclassifier()\n        return super()._new_optimizer()\n\n    def train_step(self, *args, **kwargs):\n        assert_frozen_preclassifier(self.model)\n        result = super().train_step(*args, **kwargs)\n        assert_frozen_preclassifier(self.model)\n        return result\n\n\nclass FrozenPreClassifierCAUPool(FrozenPreClassifierMixin, FixedMemoryCAUV1AdapterPool):\n    pass\n\n\nclass FrozenPreClassifierHeadOnlyPool(FrozenPreClassifierMixin, FixedMemoryHeadOnlyCAUV1AdapterPool):\n    pass\n', 'experiments/day19_linear_classifier_control.py': '"""Within-DistilBERT pre-classifier freeze using the unmodified frozen trainer."""\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\nimport sys\n\nimport pandas as pd\nimport torch\nfrom experiments import day8_fixed_memory_recurrence as trainer\nfrom src.adapter_pool_frozen_preclassifier import (\n    FrozenPreClassifierCAUPool, FrozenPreClassifierHeadOnlyPool)\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--architecture\', choices=[\'private\', \'head_only\'], required=True)\n    parser.add_argument(\'--preclassifier-mode\', choices=[\'frozen\', \'inherited\'], default=\'frozen\')\n    parser.add_argument(\'--seed\', type=int, required=True)\n    parser.add_argument(\'--order\', choices=[\'canonical\', \'b_first\'], required=True)\n    parser.add_argument(\'--output\', required=True)\n    parser.add_argument(\'--deadline-utc\', required=True)\n    args = parser.parse_args()\n    if args.preclassifier_mode == \'frozen\':\n        trainer.FixedMemoryCAUV1AdapterPool = FrozenPreClassifierCAUPool\n        trainer.FixedMemoryHeadOnlyCAUV1AdapterPool = FrozenPreClassifierHeadOnlyPool\n    sys.argv = [\'day8_fixed_memory_recurrence\', \'--regime\', \'banking\', \'--architecture\', args.architecture,\n        \'--policy\', \'cau\', \'--seed\', str(args.seed), \'--order\', args.order,\n        \'--output\', args.output, \'--deadline-utc\', args.deadline_utc]\n    trainer.main()\n    folder = Path(args.output)\n    provenance = json.loads((folder/\'provenance.json\').read_text())\n    provenance.update(preclassifier_mode=args.preclassifier_mode,\n        diagnostic_spec_sha256=hashlib.sha256(Path(\'notes/day19_linear_classifier_spec.md\').read_bytes()).hexdigest(),\n        wrapper_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n        freeze_implementation_sha256=hashlib.sha256(Path(\'src/adapter_pool_frozen_preclassifier.py\').read_bytes()).hexdigest(),\n        override_scope=\'pre-classifier trainability and its optimizer inclusion only\')\n    (folder/\'provenance.json\').write_text(json.dumps(provenance, indent=2)+\'\\n\')\n    summary = json.loads((folder/\'summary.json\').read_text())\n    route = pd.read_csv(folder/\'routing.csv\')\n    assert summary[\'status\'] == \'completed\' and len(route) == 80\n    assert route.replay_items.max() <= 512 and route.num_adapters.max() <= 8\n    reference = Path(f\'results/day8_banking_{args.architecture}_cau_seed{args.seed}_{args.order}_fixed512\')\n    rp = json.loads((reference/\'provenance.json\').read_text())\n    assert provenance[\'stream_sha256\'] == rp[\'stream_sha256\']\n    state = torch.load(folder/\'checkpoint/learner_state.pt\', map_location=\'cpu\', weights_only=False)\n    if args.preclassifier_mode == \'frozen\':\n        originals = {name.rsplit(\'.\', 1)[-1]: value for name, value in state[\'heads\'].items()\n                     if \'.pre_classifier.original_module.\' in name}\n        assert set(originals) == {\'weight\', \'bias\'}\n        for name, value in state[\'heads\'].items():\n            if \'.pre_classifier.\' in name:\n                assert torch.equal(value, originals[name.rsplit(\'.\', 1)[-1]])\n        # Dormant PEFT copies remain stored; count them explicitly, not as trained capacity.\n        summary[\'resources\'][\'frozen_private_preclassifier_parameters\'] = sum(\n            value.numel() for name, value in state[\'heads\'].items()\n            if \'.pre_classifier.modules_to_save.\' in name)\n        summary[\'resources\'][\'stored_output_classifier_parameters\'] = sum(\n            value.numel() for name, value in state[\'heads\'].items()\n            if \'.classifier.modules_to_save.\' in name)\n        (folder/\'summary.json\').write_text(json.dumps(summary, indent=2)+\'\\n\')\n    else:\n        from experiments.day15_weight_moment_recurrence import verify_replay\n        receipt = verify_replay(folder, reference)\n        (folder/\'reference_replay_verification.json\').write_text(json.dumps(receipt, indent=2)+\'\\n\')\n        print(\'LINEAR_CONTROL_UNCHANGED_WRAPPER_BITWISE_REPLAY_PASS\', flush=True)\n    print(\'LINEAR_CLASSIFIER_CONTROL_TRAJECTORY_PASS\', args.preclassifier_mode, args.architecture, args.seed, args.order, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day19_linear_classifier_integrity.py': '"""Tiny real PEFT/AdamW gates for frozen pre-classifier behavior."""\nimport argparse\nimport torch\nfrom transformers import DistilBertConfig, DistilBertForSequenceClassification\nfrom peft import LoraConfig, TaskType, get_peft_model\nfrom experiments.signal_scan import seed_all, encode\nfrom experiments.day3_action_utility_unit import nested_equal\nfrom experiments.day5_shared_head_integrity import Tokenizer, snapshot, check\nfrom src.adapter_pool_frozen_preclassifier import (\n    FrozenPreClassifierCAUPool, FrozenPreClassifierHeadOnlyPool, assert_frozen_preclassifier)\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--device\', choices=[\'cpu\', \'cuda\'], required=True)\n    args = parser.parse_args()\n    device = torch.device(args.device)\n    torch.set_num_threads(2)\n    for architecture, kind in [(\'private\', FrozenPreClassifierCAUPool), (\'head_only\', FrozenPreClassifierHeadOnlyPool)]:\n        seed_all(2032)\n        base = DistilBertForSequenceClassification(DistilBertConfig(vocab_size=64,dim=32,\n            hidden_dim=64,n_heads=4,n_layers=2,num_labels=3,dropout=.1,attention_dropout=.1,seq_classif_dropout=.1))\n        cfg = LoraConfig(task_type=TaskType.SEQ_CLS,r=2,lora_alpha=4,lora_dropout=0.,\n                         target_modules=[\'q_lin\',\'v_lin\'],bias=\'none\')\n        model = get_peft_model(base,cfg).to(device)\n        pool = kind(model=model,tokenizer=Tokenizer(),lora_config=cfg,device=device,lr=2e-4,\n            memory_size=32,total_memory_budget=32,memory_probe=4,max_adapters=8,threshold=0.,seed=2032)\n        texts,labels=[\'good item\',\'bad item\',\'new item\',\'old item\'],[0,1,2,0]\n        for _ in range(3):pool.train_step(\'default\',texts,labels)\n        pool.warmup_name=None\n        assert_frozen_preclassifier(model)\n        allowed = [n for n,p in model.named_parameters() if p.requires_grad]\n        check(architecture+\' only declared parameters trainable\',all(\'.classifier.modules_to_save.\' in n or\n              architecture==\'private\' and \'lora_\' in n for n in allowed))\n        check(architecture+\' exactly one linear output classifier\',sum(\'.classifier.modules_to_save.\' in n for n in allowed)==2)\n        before=snapshot(pool)\n        pool.crossfit_action_utility(texts,labels,\'default\')\n        check(architecture+\' crossfit exact restoration\',nested_equal(before,snapshot(pool)))\n        trial=pool.shadow_reuse(\'default\',texts,labels,texts,labels,\'default\')\n        check(architecture+\' inherited shadow exact restoration\',nested_equal(before,snapshot(pool)))\n        pool.train_step(\'default\',texts,labels);model.eval()\n        with torch.no_grad():actual=float(model(**encode(pool.tok,texts,device),labels=torch.tensor(labels,device=device)).loss)\n        check(architecture+\' inherited intervention equals real update\',abs(actual-trial[\'query_after\'])<1e-7)\n        new=pool.spawn();pool.train_step(new,texts,labels);assert_frozen_preclassifier(model)\n        pool.assert_memory_budget()\n        check(architecture+\' spawned preclassifier matches original\',True)\n        if architecture==\'head_only\':\n            check(\'linear-head-only LoRA remains zero and frozen\',all(not p.requires_grad for n,p in model.named_parameters() if \'lora_\' in n)\n                  and all(torch.count_nonzero(p)==0 for n,p in model.named_parameters() if \'lora_B\' in n))\n            check(\'linear-head-only optimizer has two parameters\',all(len(s.optimizer.param_groups[0][\'params\'])==2 for s in pool.states.values()))\n    print(\'LINEAR_CLASSIFIER_INTEGRITY_PASS\',args.device,flush=True)\n\n\nif __name__==\'__main__\':main()\n', 'experiments/day19_linear_classifier_report.py': '"""Retain every within-backbone linear-classifier control and original comparison."""\nimport json\nfrom pathlib import Path\nimport pandas as pd\nfrom experiments.day5_report import markdown_table\nfrom experiments.day6_diagnostic_report import interval\n\n\ndef main():\n    rows, pairs, deployments, incomplete = [], [], [], []\n    for seed in range(2027, 2032):\n        for order in [\'canonical\', \'b_first\']:\n            routes = {}\n            for architecture in [\'private\', \'head_only\']:\n                folder = Path(f\'results/day19_banking_{architecture}_seed{seed}_{order}_frozen_preclassifier\')\n                if not folder.exists():\n                    continue\n                if not (folder/\'summary.json\').exists() or json.loads((folder/\'summary.json\').read_text())[\'status\'] != \'completed\':\n                    incomplete.append(folder.name)\n                    continue\n                p = json.loads((folder/\'provenance.json\').read_text())\n                s = json.loads((folder/\'summary.json\').read_text())\n                assert p[\'preclassifier_mode\'] == \'frozen\'\n                route = pd.read_csv(folder/\'routing.csv\')\n                assert len(route) == 80\n                reference = Path(f\'results/day8_banking_{architecture}_cau_seed{seed}_{order}_fixed512\')\n                rp = json.loads((reference/\'provenance.json\').read_text())\n                assert p[\'stream_sha256\'] == rp[\'stream_sha256\']\n                old = pd.read_csv(reference/\'routing.csv\')\n                changed = (route.decision != old.decision) | (route.adapter.fillna(\'DEFER\') != old.adapter.fillna(\'DEFER\'))\n                rows.append({\'seed\':seed, \'order\':order, \'architecture\':architecture,\n                    \'allocation_disagreements_vs_trainable_stack\':int(changed.sum()),\n                    \'spawn_steps\':json.dumps(route.loc[route.decision==\'spawn\',\'step\'].tolist()),\n                    \'learning_updates\':s[\'learning_updates\'], \'adapters\':len(s[\'final_adapters\']),\n                    \'stored_lora_parameters\':s[\'resources\'][\'lora_parameters\'],\n                    \'stored_output_classifier_parameters\':s[\'resources\'][\'stored_output_classifier_parameters\'],\n                    \'stored_frozen_preclassifier_parameters\':s[\'resources\'][\'frozen_private_preclassifier_parameters\'],\n                    \'optimizer_bytes\':s[\'resources\'][\'optimizer_state_bytes\'],\n                    \'maximum_training_texts\':int(route.replay_items.max())})\n                routes[architecture] = route\n                final = pd.read_csv(folder/\'label_free_eval.csv\')\n                final = final[final.step == 80]\n                assert len(final) == 9\n                for rule, group in final.groupby(\'rule\'):\n                    deployments.append({\'seed\':seed,\'order\':order,\'architecture\':architecture,\n                                        \'rule\':rule,\'final_macro_accuracy\':group.accuracy.mean()})\n            if set(routes) == {\'private\', \'head_only\'}:\n                a, b = routes[\'private\'], routes[\'head_only\']\n                changed = (a.decision != b.decision) | (a.adapter.fillna(\'DEFER\') != b.adapter.fillna(\'DEFER\'))\n                pairs.append({\'seed\':seed,\'order\':order,\'allocation_disagreements\':int(changed.sum()),\n                    \'private_spawn_steps\':json.dumps(a.loc[a.decision==\'spawn\',\'step\'].tolist()),\n                    \'head_only_spawn_steps\':json.dumps(b.loc[b.decision==\'spawn\',\'step\'].tolist()),\n                    \'private_learning_updates\':int(a.train_executed.sum()),\n                    \'head_only_learning_updates\':int(b.train_executed.sum())})\n    report = [\'# Frozen hidden pre-classifier allocation diagnostic\', \'\',\n        f\'Completed trajectories {len(rows)}/20; paired controls {len(pairs)}/10. Incomplete attempts: {incomplete}.\', \'\',\n        \'Both controls use the same DistilBERT backbone and fixed hidden pre-classifier. \'\n        \'The private condition trains LoRA and the linear output classifier; the other \'\n        \'trains only the output classifier, keeping LoRA output zero. This removes \'\n        \'hidden pre-classifier learning, with its associated optimizer state, in both \'\n        \'conditions. It is an allocation diagnostic, not a tuned competitive benchmark. \'\n        \'The retained PEFT pre-classifier copies are dormant stored parameters.\', \'\']\n    pd.DataFrame(rows).to_csv(\'results/day19_linear_classifier_trajectories.csv\', index=False)\n    pd.DataFrame(pairs, columns=[\'seed\',\'order\',\'allocation_disagreements\',\'private_spawn_steps\',\n        \'head_only_spawn_steps\',\'private_learning_updates\',\'head_only_learning_updates\']).to_csv(\n            \'results/day19_linear_classifier_allocation_pairs.csv\', index=False)\n    pd.DataFrame(deployments).to_csv(\'results/day19_linear_classifier_deployment.csv\', index=False)\n    summaries = []\n    if deployments:\n        frame = pd.DataFrame(deployments)\n        paired = frame.pivot(index=[\'seed\',\'order\',\'rule\'],columns=\'architecture\',values=\'final_macro_accuracy\').dropna()\n        if not paired.empty and {\'private\',\'head_only\'} <= set(paired.columns):\n            paired[\'private_minus_head_only\'] = paired.private-paired.head_only\n            for rule, group in paired.reset_index().groupby(\'rule\'):\n                complete = group.groupby(\'seed\').filter(lambda g:len(g)==2 and set(g.order)=={\'canonical\',\'b_first\'})\n                values = complete.groupby(\'seed\').private_minus_head_only.mean()\n                if len(values):summaries.append({\'rule\':rule,**interval(values)})\n    summary = pd.DataFrame(summaries, columns=[\'rule\',\'seed_clusters\',\'mean\',\'ci_low\',\'ci_high\'])\n    summary.to_csv(\'results/day19_linear_classifier_prediction_differences.csv\', index=False)\n    report += [\'## Every allocation pair\',\'\',markdown_table(pd.DataFrame(pairs)),\'\',\n        \'## All deviations from the trainable-stack reference and stored resources\',\'\',markdown_table(pd.DataFrame(rows)),\'\',\n        \'## All private-minus-output-classifier-only accuracy differences\',\'\',markdown_table(summary),\'\',\n        \'## Every deployment outcome\',\'\',markdown_table(pd.DataFrame(deployments)),\'\',\n        \'Intervals are descriptive over paired training seeds and fixed repeatedly examined \'\n        \'development examples. Neither agreement nor disagreement establishes a universal \'\n        \'capacity principle. Existing controls with trainable hidden classifiers must not \'\n        \'be described as having no learned hidden representation capacity.\']\n    Path(\'notes/day19_linear_classifier_results.md\').write_text(\'\\n\'.join(report)+\'\\n\')\n    print(\'LINEAR_CLASSIFIER_REPORT_SAVED\', len(rows), \'trajectories\', len(pairs), \'pairs\', flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'experiments/day19_linear_classifier_worker.py': '"""Isolated within-backbone frozen pre-classifier allocation controls.\n\nShares the GPU with diagnostics; timing is descriptive, not a compute benchmark.\nPublishes only to a branch of the existing mitosis-interference repository.\n"""\nfrom datetime import datetime, timezone\nimport fcntl\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\n\n\nROOT = Path(\'/workspace/mitosis-static-tuning\')\nBRANCH = \'day17-static-tuning-20261006\'\nLAUNCH_CUTOFF = datetime.fromisoformat(\'2026-10-07T03:00:00+00:00\')\nDEADLINE = \'2026-10-07T03:15:00+00:00\'\nSTATUS = Path(\'notes/day19_linear_classifier_execution.json\')\nENV = os.environ.copy()\nENV.update(OMP_NUM_THREADS=\'8\', TOKENIZERS_PARALLELISM=\'false\',\n           GIT_TERMINAL_PROMPT=\'0\', GH_PROMPT_DISABLED=\'1\')\n\n\ndef now():\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef write(path, data):\n    p = Path(path)\n    temporary = p.with_suffix(p.suffix + \'.tmp\')\n    temporary.write_text(json.dumps(data, indent=2) + \'\\n\')\n    temporary.replace(p)\n\n\ndef read(args):\n    return subprocess.check_output(args, env=ENV, text=True, timeout=90).strip()\n\n\ndef command(args, log=None):\n    print(\'RUN\', \' \'.join(args), flush=True)\n    return subprocess.run(args, env=ENV, stdin=subprocess.DEVNULL, stdout=log,\n                          stderr=subprocess.STDOUT if log else None).returncode\n\n\ndef checkpoint_manifest():\n    manifest = {}\n    for folder in sorted(Path(\'results\').glob(\'day19_*\')):\n        if not folder.is_dir():\n            continue\n        for p in sorted((folder / \'checkpoint\').rglob(\'*\')):\n            if p.is_file():\n                digest = hashlib.sha256()\n                with p.open(\'rb\') as stream:\n                    for block in iter(lambda: stream.read(8 * 1024 * 1024), b\'\'):\n                        digest.update(block)\n                manifest[str(p)] = {\'bytes\': p.stat().st_size, \'sha256\': digest.hexdigest()}\n    return manifest\n\n\ndef preserve():\n    write(\'results/day19_checkpoint_preservation_manifest.json\', checkpoint_manifest())\n    if command([\'git\', \'add\', \'-A\']):\n        raise RuntimeError(\'Staging failed\')\n    if read([\'git\', \'status\', \'--porcelain\']):\n        if command([\'git\', \'commit\', \'-m\', \'Preserve frozen pre-classifier diagnostic progress\']):\n            raise RuntimeError(\'Progress commit failed\')\n    if command([\'git\', \'push\', \'origin\', BRANCH]):\n        raise RuntimeError(\'Progress push failed; preserve local state\')\n    head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == head\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    print(\'LINEAR_CONTROL_PROGRESS_PUSHED\', head, flush=True)\n\n\ndef verify_new_checkpoint_roundtrip():\n    # This worktree intentionally retains pointers for unrelated old checkpoints.\n    # Verify newly generated Day-19 checkpoints; do not replace the main manifest.\n    snapshot = read([\'git\', \'rev-parse\', \'HEAD\'])\n    manifest = json.loads(Path(\'results/day19_checkpoint_preservation_manifest.json\').read_text())\n    lines = read([\'git\', \'lfs\', \'ls-files\', \'--long\']).splitlines()\n    by_path = {line.split(\' \', 2)[2]: line.split()[0] for line in lines}\n    tensors = {p for p in manifest if Path(p).suffix in {\'.pt\', \'.safetensors\'}}\n    assert tensors <= set(by_path)\n    for p, item in manifest.items():\n        assert Path(p).stat().st_size == item[\'bytes\']\n        assert hashlib.sha256(Path(p).read_bytes()).hexdigest() == item[\'sha256\']\n        if p in tensors:\n            assert item[\'sha256\'] == by_path[p]\n    fresh = Path(\'/workspace\') / (\'mitosis-day19-lfs-verify-\' + datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%SZ\'))\n    assert not fresh.exists()\n    if command([\'git\', \'-c\', \'lfs.storage=\' + str(fresh), \'lfs\', \'fetch\',\n                \'--include=results/day19_*/checkpoint/**\', \'--exclude=\', \'origin\', BRANCH]):\n        raise RuntimeError(\'Fresh static checkpoint download failed\')\n    oids = {by_path[p] for p in tensors}\n    for oid in oids:\n        p = fresh / \'objects\' / oid[:2] / oid[2:4] / oid\n        assert p.is_file(), \'Missing remotely downloaded static checkpoint\'\n        assert hashlib.sha256(p.read_bytes()).hexdigest() == oid\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == snapshot\n    receipt = {\'repository\': \'anitusiruk/mitosis-interference\', \'branch\': BRANCH,\n        \'preserved_snapshot_commit\': snapshot, \'verified_utc\': now(),\n        \'scope\': \'new Day-19 checkpoints only; unrelated checkpoints retain their main-branch receipts\',\n        \'all_day19_lfs_sha256_verified\': True, \'fresh_remote_lfs_fetch_returncode\': 0,\n        \'checkpoint_files\': len(manifest), \'tensor_files\': len(tensors),\n        \'unique_lfs_objects_verified\': len(oids),\n        \'checkpoint_bytes\': sum(r[\'bytes\'] for r in manifest.values())}\n    write(\'notes/day19_github_save_verification.json\', receipt)\n    print(\'LINEAR_CONTROL_REMOTE_CHECKPOINT_ROUNDTRIP_PASS\', len(oids), flush=True)\n    return receipt\n\n\ndef run_job(records, architecture, seed, order, mode):\n    name = (\'day19_reference_replay_head_only_seed2031_b_first\' if mode == \'inherited\'\n            else f\'day19_banking_{architecture}_seed{seed}_{order}_frozen_preclassifier\')\n    folder = Path(\'results\', name)\n    assert not folder.exists()\n    args = [sys.executable, \'-u\', \'-m\', \'experiments.day19_linear_classifier_control\',\n        \'--architecture\', architecture, \'--preclassifier-mode\', mode, \'--seed\', str(seed),\n        \'--order\', order, \'--output\', str(folder), \'--deadline-utc\', DEADLINE]\n    row = {\'name\': name, \'phase\': \'replay_gate\' if mode == \'inherited\' else \'diagnostic\',\n           \'status\': \'running\', \'started_utc\': now(), \'command\': args}\n    records.append(row)\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 20, \'github_save_pending\': True})\n    with Path(\'logs\', name + \'.txt\').open(\'x\') as log:\n        code = command(args, log)\n    row.update(status=\'completed\' if code == 0 else \'failed\', returncode=code, finished_utc=now())\n    if mode == \'frozen\':\n        with Path(\'logs\', name + \'_report.txt\').open(\'x\') as log:\n            report_code = command([sys.executable, \'-u\', \'-m\', \'experiments.day19_linear_classifier_report\'], log)\n        if report_code:\n            row[\'report_failed\'] = True\n            code = report_code\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 20, \'github_save_pending\': True})\n    preserve()\n    print(\'LINEAR_CONTROL_JOB\', name, row[\'status\'], flush=True)\n    if code:\n        raise RuntimeError(\'Linear-classifier discrepancy preserved: \' + name)\n\n\ndef main():\n    os.chdir(ROOT)\n    ENV[\'MITOSIS_MODEL_REVISION\'] = json.loads(Path(\'notes/restart_20261006_preflight.json\').read_text())[\'backbone_revision\']\n    lock = open(\'/workspace/mitosis-static-tuning-worker.lock\', \'a\')\n    fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n    assert read([\'git\', \'branch\', \'--show-current\']) == BRANCH\n    assert read([\'git\', \'remote\', \'get-url\', \'origin\']) == \'https://github.com/anitusiruk/mitosis-interference.git\'\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    assert json.loads(Path(\'notes/day17_static_tuning_execution.json\').read_text())[\'github_save_verified\']\n    assert not STATUS.exists()\n    records, failed, stopped = [], False, False\n    try:\n        if datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n            stopped = True\n        else:\n            run_job(records, \'head_only\', 2031, \'b_first\', \'inherited\')\n        for seed in range(2027, 2032):\n            for order in [\'canonical\', \'b_first\']:\n                for architecture in [\'private\', \'head_only\']:\n                    if stopped or datetime.now(timezone.utc) >= LAUNCH_CUTOFF:\n                        stopped = True\n                        break\n                    run_job(records, architecture, seed, order, \'frozen\')\n    except Exception as error:\n        failed = True\n        write(\'notes/day19_linear_classifier_failure.json\', {\'error\': repr(error), \'utc\': now()})\n        print(\'LINEAR_CONTROL_HALTED\', repr(error), flush=True)\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 20, \'github_save_pending\': True,\n                   \'failed\': failed, \'administratively_stopped\': stopped})\n    preserve()\n    verify_new_checkpoint_roundtrip()\n    complete = sum(r[\'phase\'] == \'diagnostic\' and r[\'status\'] == \'completed\' for r in records) == 20 and not failed\n    write(STATUS, {\'jobs\': records, \'planned_research_jobs\': 20, \'github_save_pending\': False,\n                   \'github_save_verified\': True, \'failed\': failed, \'complete\': complete,\n                   \'administratively_stopped\': stopped})\n    assert command([\'git\', \'add\', \'notes/day19_github_save_verification.json\', str(STATUS)]) == 0\n    assert command([\'git\', \'commit\', \'-m\', \'Record verified frozen pre-classifier control preservation\']) == 0\n    assert command([\'git\', \'push\', \'origin\', BRANCH]) == 0\n    head = read([\'git\', \'rev-parse\', \'HEAD\'])\n    assert read([\'git\', \'ls-remote\', \'origin\', \'refs/heads/\' + BRANCH]).split()[0] == head\n    assert not read([\'git\', \'status\', \'--porcelain\'])\n    print(\'LINEAR_CLASSIFIER_AND_GITHUB_SAVE_COMPLETE\', head, \'COMPLETE\', complete, \'FAILED\', failed, flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'notes/day19_linear_classifier_spec.md': "# Within-backbone linear-classifier allocation control\n\nDesigned after the primary DistilBERT, BERT and first weight/state development\noutcomes, before this control's outcomes. The original DistilBERT head-only control\ntrains both the hidden pre-classifier and the output classifier. It rules out a\nneed for LoRA in the observed allocation sequences, but is not a control without\nlearned hidden representation capacity. BERT's frozen-pooler linear classifier\nchanges several architecture components together and does not isolate this issue.\n\nKeep DistilBERT, its explicit pinned backbone, tokenizer, model initialization,\nrank-8 Q/V adapters, dropout, clipping, optimizer rate, incoming updates, stream,\nallocation rule and fixed 512-text memory unchanged. Freeze the pre-classifier\nfor every real and temporary package. Compare private LoRA-plus-output-classifier\nlearning with zero-output, frozen-LoRA, output-classifier-only learning. Both have\nthe same fixed hidden pre-classifier. The trainable output classifier is linear\nin this fixed head representation; input-to-logit prediction is not a globally\nlinear function of text. PEFT retains dormant private pre-classifier copies; report\nthat stored cost explicitly rather than counting it as learned capacity.\n\nUse BANKING seeds 2027–2031, both original orders, and both learning controls:\n20 complete trajectories. Preserve every original deployment rule. Report all\nprivate/head-only allocation pairs, all deviations from their trainable-stack\nreferences, all three deployment rules and all actual storage counts. Average\norders inside training seeds before descriptive Student intervals. There is no\nselection of windows, seeds, prediction rules, or architecture by outcomes.\nThis is a development diagnostic, not a tuned performance benchmark, untouched\nconfirmation, or universal capacity theorem. Freezing the hidden layer also\nremoves its optimizer state; that consequence is part of this training ablation,\nnot an independent weight-versus-state causal isolation.\n\nBefore research, pass tiny CPU and CUDA real PEFT/AdamW gates: the pre-classifier\nand its copies stay bitwise equal to the original; only the declared output\nclassifier and, in the private condition, LoRA parameters train; zero-LoRA behavior;\nexact shadow restoration; equality of inherited shadow and actual update; and\nspawn/memory invariants. Then run an 80-step unchanged-wrapper replay with freezing\ndisabled against the complete head-only seed-2031 B-first fixed-memory reference.\nRequire the entire final learner state and adapter tensors to be bitwise equal.\nAny gate failure is preserved and halts research. Never relax tolerances quietly.\n\nCommit the protocol, source and tiny gate logs before research to the existing\n`day17-static-tuning-20261006` branch of `anitusiruk/mitosis-interference`. Wait for\nthe static worker's independently verified save, then reuse its isolated worktree\nand lock. Continue sharing the GPU with the original factorial queue; timings are\ndescriptive. Save every attempt and independently fetch/hash every new checkpoint.\nThe branch integrator can acquire this lock only after the diagnostic finishes;\nits combined snapshot verification will include these checkpoints. Keep the\noriginal administrative cutoff and deadline, preserving partial coverage if needed.\n"}

from datetime import datetime,timezone
import fcntl,hashlib,json,os,subprocess,sys,time
from pathlib import Path
ROOT=Path('/workspace/mitosis-static-tuning')
BRANCH='day17-static-tuning-20261006'
ENV=os.environ.copy();ENV.update(GIT_TERMINAL_PROMPT='0',GH_PROMPT_DISABLED='1',OMP_NUM_THREADS='8',TOKENIZERS_PARALLELISM='false')
def read(args):return subprocess.check_output(args,cwd=ROOT,env=ENV,text=True,timeout=90).strip()
def run(args,log=None):
 print('RUN',' '.join(args),flush=True)
 return subprocess.run(args,cwd=ROOT,env=ENV,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT if log else None).returncode
os.chdir(ROOT)
lock=open('/workspace/mitosis-static-tuning-worker.lock','a')
while True:
 if datetime.now(timezone.utc)>=datetime.fromisoformat('2026-10-07T02:30:00+00:00'):raise RuntimeError('Linear-control installation cutoff; no research launched')
 try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 except BlockingIOError:
  print('LINEAR_CONTROL_WAITING_FOR_STATIC_VERIFIED_SAVE',datetime.now(timezone.utc).isoformat(),flush=True);time.sleep(15);continue
 state=json.loads(Path('notes/day17_static_tuning_execution.json').read_text())
 if state.get('github_save_verified'):break
 fcntl.flock(lock,fcntl.LOCK_UN);time.sleep(15)
assert state.get('complete') and not state.get('failed'),'Inspect incomplete static research before adding another control'
assert read(['git','branch','--show-current'])==BRANCH
assert read(['git','remote','get-url','origin'])=='https://github.com/anitusiruk/mitosis-interference.git'
assert not read(['git','status','--porcelain'])
assert read(['git','rev-parse','HEAD'])==read(['git','ls-remote','origin','refs/heads/'+BRANCH]).split()[0]
for name,source in FILES.items():
 p=Path(name);assert not p.exists();p.write_text(source);print('LINEAR_CONTROL_SOURCE',name,hashlib.sha256(p.read_bytes()).hexdigest(),flush=True)
code=run([sys.executable,'-m','compileall','-q',*[p for p in FILES if p.endswith('.py')]])
for device in ['cpu','cuda']:
 with Path('logs','day19_linear_classifier_gate_'+device+'.txt').open('x') as log:
  if code==0:code=run([sys.executable,'-u','-m','experiments.day19_linear_classifier_integrity','--device',device],log)
Path('notes/day19_prelaunch_gate.json').write_text(json.dumps({'utc':datetime.now(timezone.utc).isoformat(),'gate_returncode':code,'research_outcomes_generated':False,'gates':'CPU and CUDA tiny real PEFT/AdamW transactions and frozen pre-classifier invariants'},indent=2)+'\n')
