assert read(['git','ls-remote','origin','refs/heads/'+BRANCH]).split()[0]==head
assert not read(['git','status','--porcelain'])
print('LINEAR_CLASSIFIER_PREREGISTRATION_PUSHED',head,'TINY_GATE',code,flush=True)
